// 문법은 다르지만 하는 말은 같다: 이 값이 바뀌면 저 화면을 고쳐라

// 나쁨. 이 카드는 너무 많은 것을 안다
<Card title={t} desc={d} img={i} badge={b} onLike={f} liked={l} author={a} date={dt} />

// 좋음 ① 관련된 것을 묶는다
<Card post={post} onLike={handleLike} />

// 좋음 ② 자리를 내주고 내용은 부르는 쪽이 채운다 (합성)
<Card>
  <Card.Media src={post.img} />
  <Card.Title>{post.title}</Card.Title>
  <Card.Actions><LikeButton id={post.id} /></Card.Actions>
</Card>

// ① 파생을 상태로
const [items, setItems] = useState([]);
const [total, setTotal] = useState(0);        // 나쁨. 어긋난다
const total = items.reduce((s, i) => s + i.price, 0);   // 좋음

// ② props 를 상태로 복사 (초기값 이후 갱신이 안 된다)
const [name, setName] = useState(props.name);  // 주의: props 가 바뀌어도 그대로

// ③ 서버 자료를 손으로 관리
const [posts, setPosts] = useState([]);
useEffect(() => { fetch('/posts').then(r => r.json()).then(setPosts); }, []);
// 로딩, 오류, 재요청, 중복 제거, 캐시를 전부 손으로 → 7장의 도구로

// 렌더마다 새 객체, 새 함수 → 자식의 비교가 늘 실패한다
<Child style={{ margin: 8 }} onSave={() => save(id)} items={items.filter(Boolean)} />

// 고치는 방향
const style = { margin: 8 };                 // 렌더 밖으로
const onSave = useCallback(() => save(id), [id]);
const visible = useMemo(() => items.filter(Boolean), [items]);

// 다만: 이것도 비용이다. 프로파일러로 문제를 확인한 뒤에 하라

// 안전한 경우: 목록이 절대 바뀌지 않는다 (순서 변경, 삽입, 삭제 없음)
{STATIC_TABS.map((t, i) => <Tab key={i} {...t} />)}

// 위험한 경우: 정렬, 필터, 삽입, 삭제가 있다
{todos.map((t, i) => <Row key={i} todo={t} />)}     // 나쁨
{todos.map((t) => <Row key={t.id} todo={t} />)}     // 좋음

// id 가 없으면? 만들어라 (crypto.randomUUID() 를 자료 생성 시점에 한 번)

useEffect(() => {
  const ac = new AbortController();
  (async () => {
    try {
      const res = await fetch(`/u/${id}`, { signal: ac.signal });
      setUser(await res.json());
    } catch (e) {
      if (e.name !== 'AbortError') setError(e);
    }
  })();
  return () => ac.abort();      // 떠나거나 id 가 바뀌면 이전 요청을 끊는다
}, [id]);

// 읽기. 캐시, 중복 제거, 재검증이 기본으로 따라온다
const { data, isPending, error } = useQuery({
  queryKey: ['posts', page],
  queryFn: () => api(`/posts?page=${page}`, PostList),   // TS 5장의 검증과 함께
});

// 쓰기. 성공하면 관련 목록을 무효화
const mutate = useMutation({
  mutationFn: createPost,
  onSuccess: () => queryClient.invalidateQueries({ queryKey: ['posts'] }),
});

// 서버에는 window 가 없다
if (typeof window !== 'undefined') { /* 브라우저 전용 */ }

// 브라우저에서만 필요한 무거운 것은 나중에 불러온다
const Chart = lazy(() => import('./Chart'));

// 서버 전용 값이 번들에 새지 않게 (환경변수 접두사 규칙을 지켜라)
process.env.DATABASE_URL          // 서버 전용
import.meta.env.VITE_API_URL      // 브라우저에 노출됨. 비밀 금지
